-- Generated by tk/scripts/build_energy_base_raw_from_cdf.py (relations)
SELECT
    cast(`key` AS STRING) AS externalId
  , CASE WHEN coalesce(trim(`assetExternalId`), '') = '' THEN NULL ELSE node_reference(trim(`assetSpace`), trim(`assetExternalId`)) END AS `asset`
  , CASE WHEN coalesce(trim(`loopExternalId`), '') = '' THEN NULL ELSE node_reference(trim(`loopSpace`), trim(`loopExternalId`)) END AS `loop`
FROM `{{energyBaseRawDb}}`.`InspectionRecommendation`
